    "status" varchar(20) DEFAULT 'AVAILABLE'::character varying CHECK ((status)::text = ANY (ARRAY[('AVAILABLE'::character varying)::text, ('SOLD'::character varying)::text, ('RESERVED'::character varying)::text])),
    "customer_id" int4,
    "sold_date" date,
    "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

